import hashlib,json,os,re,shutil,statistics,subprocess,tempfile,time
from pathlib import Path
os.sched_setaffinity(0,{0})
binaries={k:str(Path(v).resolve()) for k,v in {'parent':'build/review-j17-lock-final/release/mus-solver','candidate':'build/review-j17-sync-final/release/mus-solver'}.items()}
data={'method':'Three alternating paired runs, CPU0, one worker, seed7. Files saved on workspace Btrfs, not /tmp tmpfs. Five further pairs if 20% time or 25% RSS gate is triggered. Parent completion includes buffered close and rename; candidate completion also confirms file and directory writes. Exclude mutable lock metadata; compare checkpoint and values bytes and normalized extension manifests. No own concurrent builds/tests.','parent_commit':'1f1dec7','runs':[],'summary':[]}
def digest(p):
 h=hashlib.sha256()
 with open(p,'rb') as f:
  for chunk in iter(lambda:f.read(1024*1024),b''):h.update(chunk)
 return h.hexdigest()
for key,name in [('binary','mus-solver'),('library','libmus_solver.a'),('bot','mus-bot')]:data[key+'_sha256']={v:digest(Path(p).parent/name) for v,p in binaries.items()}
assert len(set(data['library_sha256'].values()))==len(set(data['bot_sha256'].values()))==1
output=Path('/tmp/mus-review-j17-sync-performance.json')
def save():output.write_text(json.dumps(data,indent=2)+'\n')
def hashes(directory,all_files=False):return {p.name:digest(p) for p in sorted(directory.iterdir()) if p.is_file() and (all_files or p.name=='values.txt' or p.name.endswith('.cfr.zst'))}
def run(group,version,args,repeat):
 command=[binaries[version],*args]
 with tempfile.TemporaryFile(mode='w+') as log:
  start=time.perf_counter();pid=os.posix_spawn(command[0],command,os.environ,file_actions=[(os.POSIX_SPAWN_DUP2,log.fileno(),1),(os.POSIX_SPAWN_DUP2,log.fileno(),2)])
  _,status,usage=os.wait4(pid,0);elapsed=time.perf_counter()-start;log.seek(0);stdout=log.read()
 if status:raise RuntimeError((command,status,stdout))
 row={'group':group,'version':version,'repeat':repeat,'command':command,'wall_seconds':elapsed,'peak_rss_kib':usage.ru_maxrss,'stdout':stdout}
 data['runs'].append(row);save();print(group,version,repeat,round(elapsed,6),usage.ru_maxrss,flush=True);return row

def summarize(group,confirmation=False):
 rows=[r for r in data['runs'] if r['group']==group and (r['repeat']>3)==confirmation];s={'group':group,'confirmation':confirmation}
 for metric in ['wall_seconds','peak_rss_kib']:
  a=statistics.median(r[metric] for r in rows if r['version']=='parent');b=statistics.median(r[metric] for r in rows if r['version']=='candidate');s[metric]={'parent':a,'candidate':b,'change_percent':100*(b/a-1)}
 s['gate_triggered']=s['wall_seconds']['change_percent']>=20 or s['peak_rss_kib']['change_percent']>=25
 data['summary'].append(s);save();print('SUMMARY',json.dumps(s),flush=True);return s['gate_triggered']

with tempfile.TemporaryDirectory(prefix='persistence-',dir=str(Path('build/review-j17-sync-io').resolve())) as tmp:
 root=Path(tmp);base_source=root/'base-source'
 subprocess.run([binaries['parent'],'--format','ordago-score','--score','35:35','--iterations','100','--evaluation-samples','10000','--seed','7','--continuation',str(base_source)],check=True,stdout=subprocess.DEVNULL)
 source_hashes=hashes(base_source,True);data['extension_source_sha256']=source_hashes
 for group in ['public-raw-save','public-zstd-save','score','extension']:
  reference=None;manifest=None
  def pair(repeat):
   global reference,manifest
   for version in (['parent','candidate'] if repeat%2==0 else ['candidate','parent']):
    directory=root/f'{group}-{version}-{repeat}'
    if group.startswith('public'):
     checkpoint=directory.with_suffix('.cfr' if group=='public-raw-save' else '.cfr.zst')
     args=['--format','ordago-public','--iterations','500','--seed','7','--save' if group=='public-raw-save' else '--save-compressed',str(checkpoint)]
    else:
     args=['--format','ordago-score','--score','35:35','--iterations','1000','--evaluation-samples','10000','--continuation',str(directory)]
     if group=='extension':
      source=root/f'source-{version}-{repeat}';shutil.copytree(base_source,source)
      args+=['--extend-continuation',str(source)]
     else:args+=['--seed','7']
    # Clear earlier dirty writes outside the timed process, including cloned sources.
    # This makes each candidate and parent start with no own prior pending writes.
    fd=os.open(root,os.O_RDONLY|os.O_DIRECTORY)
    try:
     import ctypes
     libc=ctypes.CDLL(None,use_errno=True)
     if libc.syncfs(fd)!=0:raise OSError(ctypes.get_errno(),'syncfs')
    finally:os.close(fd)
    row=run(group,version,args,repeat+1)
    h={'checkpoint':digest(checkpoint)} if group.startswith('public') else hashes(directory)
    if not group.startswith('public'):assert len(h)==46
    if reference is None:reference=h
    assert h==reference;row['files_identical']=True;row['file_sha256']=h
    if group=='extension':
     assert hashes(source,True)==source_hashes
     text=(directory/'extension.txt').read_text().replace(str(source),'<SOURCE>')
     if manifest is None:manifest=text
     assert text==manifest;row['source_preserved']=True;row['normalized_manifest_sha256']=hashlib.sha256(text.encode()).hexdigest()
     shutil.rmtree(source)
    if group.startswith('public'):
     row['checkpoint_bytes']=checkpoint.stat().st_size
     checkpoint.unlink()
    else:shutil.rmtree(directory)
    save()
  for repeat in range(3):pair(repeat)
  if summarize(group):
   for repeat in range(3,8):pair(repeat)
   if summarize(group,True):
    data['blocked']=True;save();print('CONFIRMED_PERFORMANCE_GATE',flush=True);break
 else:data['blocked']=False;save();print('ALL_CHECKS_PASSED',flush=True)
